import crypto from 'node:crypto'
import fs from 'node:fs'
import zlib from 'node:zlib'

const FIXTURE_TEXT = 'Approved English dialogue.'
const COMPRESSED_WAVE_BASE64 = ''
const WAVE_BYTES = zlib.gunzipSync(Buffer.from(COMPRESSED_WAVE_BASE64, 'base64'))

function sha256(value) {
  return crypto.createHash('sha256').update(value).digest('hex')
}

export const redrawLocalEnglishVoiceFixture = Object.freeze({
  source: 'test_only_local_fixture',
  generator: 'Microsoft Zira Desktop',
  voice: 'Microsoft Zira Desktop en-US',
  locale: 'en-US',
  text: FIXTURE_TEXT,
  text_sha256: sha256(FIXTURE_TEXT),
  audio_sha256: sha256(WAVE_BYTES),
  mime_type: 'audio/wav',
  sample_rate: 22050,
  channels: 1,
  test_only: true,
  production_manifest_eligible: false,
  acceptance_scope: 'test_fixture_only_not_espeak_ng_acceptance',
})

const RAFAEL_SUPPLEMENTAL_TEXT = 'Welcome home, son.'

export const redrawLocalEnglishVoiceSupplementalDialogue = Object.freeze({
  shot_id: 'shot-6',
  source_character_key: 'rafael',
  target_text: RAFAEL_SUPPLEMENTAL_TEXT,
  source_translation: false,
})

export const redrawLocalEnglishVoiceProfiles = Object.freeze(
  ['diego', 'elena', 'lucas', 'mateo', 'rafael'].map((characterKey, index) => Object.freeze({
    profile_key: `test-en-us-${index + 1}-${characterKey}`,
    locale: 'en-US',
    voice: `en-us-test-${index + 1}`,
    pitch: 35 + index,
    rate: 165 + index,
    amplitude: 95 + index,
  })),
)

export function writeRedrawLocalEnglishVoiceFixture(outputPath) {
  fs.writeFileSync(outputPath, WAVE_BYTES, { flag: 'wx', mode: 0o600 })
  return { ...redrawLocalEnglishVoiceFixture, output_path: outputPath }
}
